"""Pydantic models for Strata SDK responses."""

from __future__ import annotations

from datetime import datetime

from pydantic import BaseModel, Field, field_validator


class Memory(BaseModel):
    """A stored memory entry."""

    id: str
    type: str = ""
    summary: str = ""
    details: str = ""
    tags: list[str] = Field(default_factory=list)
    project: str = ""
    timestamp: datetime | None = None

    def __repr__(self) -> str:
        tag_str = f" [{', '.join(self.tags)}]" if self.tags else ""
        return f"Memory(id={self.id!r}, type={self.type!r}, summary={self.summary[:60]!r}{tag_str})"


class SearchResult(BaseModel):
    """A search result from Strata."""

    text: str
    score: float = 0.0
    project: str = ""
    session_id: str = ""
    date: str = ""
    tools: list[str] = Field(default_factory=list)

    @field_validator("tools", mode="before")
    @classmethod
    def _coerce_tools(cls, v: object) -> list[str]:
        if isinstance(v, str):
            return [v] if v else []
        if isinstance(v, list):
            return v
        return []

    def __repr__(self) -> str:
        return f"SearchResult(score={self.score:.2f}, text={self.text[:60]!r})"


class IngestResult(BaseModel):
    """Result of ingesting a conversation."""

    model_config = {"populate_by_name": True}

    session_id: str = Field(default="", alias="sessionId")
    entries_extracted: int = Field(default=0, alias="entriesExtracted")
    entities_found: int = Field(default=0, alias="entitiesFound")
    procedures_found: int = Field(default=0, alias="proceduresFound")
    conflicts_resolved: int = Field(default=0, alias="conflictsResolved")
    summary: str = ""
    warnings: list[str] = Field(default_factory=list)

    def __repr__(self) -> str:
        return (
            f"IngestResult(entries={self.entries_extracted}, "
            f"entities={self.entities_found}, procedures={self.procedures_found})"
        )


class HistoryEvent(BaseModel):
    """A history event for a memory entry."""

    event: str
    timestamp: datetime | None = None
    old_value: str = ""
    new_value: str = ""

    def __repr__(self) -> str:
        return f"HistoryEvent(event={self.event!r}, timestamp={self.timestamp})"


class Project(BaseModel):
    """A project tracked by Strata."""

    name: str
    session_count: int = 0
    last_indexed: datetime | None = None

    def __repr__(self) -> str:
        return f"Project(name={self.name!r}, sessions={self.session_count})"
